import { createHash } from "node:crypto";
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const skillName = "aido-discoverability-check";
const skillRoot = resolve(projectRoot, "skills", skillName);
const outputPath = resolve(projectRoot, "src", "generated", "aido-skill-bundle.js");
const uriRoot = `skill://aido-discoverability/${skillName}`;

async function listFiles(directory) {
  const entries = await readdir(directory, { withFileTypes: true });
  const files = [];
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const path = resolve(directory, entry.name);
    if (entry.isDirectory()) files.push(...await listFiles(path));
    else if (entry.isFile() && !entry.name.startsWith(".")) files.push(path);
  }
  return files;
}

function parseFrontmatter(text) {
  const match = text.match(/^---\n([\s\S]*?)\n---\n/);
  if (!match) throw new Error("SKILL.md is missing YAML frontmatter");
  const frontmatter = {};
  for (const line of match[1].split("\n")) {
    const separator = line.indexOf(":");
    if (separator < 1) continue;
    const key = line.slice(0, separator).trim();
    let value = line.slice(separator + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    frontmatter[key] = value;
  }
  if (frontmatter.name !== skillName || !frontmatter.description) throw new Error("SKILL.md frontmatter is incomplete or inconsistent");
  return frontmatter;
}

const files = await listFiles(skillRoot);
const resources = [];
let skillText = "";
for (const path of files) {
  const resourcePath = relative(skillRoot, path).split("\\").join("/");
  const text = await readFile(path, "utf8");
  if (resourcePath === "SKILL.md") skillText = text;
  resources.push({
    uri: `${uriRoot}/${resourcePath}`,
    digest: `sha256:${createHash("sha256").update(text, "utf8").digest("hex")}`,
    mimeType: resourcePath.endsWith(".yaml") ? "application/yaml" : "text/markdown",
    text
  });
}
if (!skillText) throw new Error("SKILL.md was not found");

const bundle = {
  uri: `${uriRoot}/SKILL.md`,
  frontmatter: parseFrontmatter(skillText),
  resources
};
const generated = `// Generated by scripts/generate-skill-bundle.mjs. Do not edit by hand.\nexport const AIDO_SKILL_BUNDLE = Object.freeze(${JSON.stringify(bundle, null, 2)});\n`;
await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, generated, "utf8");
console.log(`Generated ${relative(projectRoot, outputPath)} with ${resources.length} resources.`);
